// Author: MiYu. A live source fixture checks nighttime cloaking, moving detection buffs and temporary reveal lifecycle.
#include "session.h"
#include "setup.h"
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_stealth_tests <data-root> <fixture> [flow|dust|meld|tower|sentinel|visible-ghost]");std::wstring mode=argc>3?argv[3]:L"flow";if(mode!=L"flow" && mode!=L"dust" && mode!=L"meld" && mode!=L"tower" && mode!=L"sentinel" && mode!=L"visible-ghost")throw std::runtime_error("Unknown stealth check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto archer=vm.global("archer"),hero=vm.global("hero"),shade=vm.global("shade");auto p0=call("Player",{vm.integer(0)});auto type=[&](const char* code){return vm.integer(int(ObjectData::code(code)));};auto point=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto daytime=[&](int hour){call("SetFloatGameState",{vm.global("GAME_STATE_TIME_OF_DAY"),point(hour)});};auto move=[&](jass::Value unit,int x,int y){call("SetUnitPosition",{unit,point(x),point(y)});};
        require(session.unitInvisible(shade.bits) && session.unitInvisibleTo(shade.bits,0),"Source Ghost did not hide the enemy Shade");
        if(mode==L"visible-ghost"){
            auto p1=call("Player",{vm.integer(1)});auto target=call("CreateUnit",{p1,type("hfoo"),point(256),point(0),point(0)});require(target.bits && call("UnitAddAbility",{target,type("Aeth")}).bits,"Visible Ghost ability not added");auto& passive=session.passiveInfo(ObjectData::code("Aeth"),1);require(passive.kind==PassiveKind::VisibleGhost && passive.amount==1 && passive.secondary==1,"Visible Ghost flags do not use the source fields");require(!session.unitInvisible(target.bits),"Visible Ghost incorrectly turned the unit invisible");std::optional<WorldPoint> site;std::string reason;for(int x=-2048;x<=2048 && !site;x+=256)for(int y=-2048;y<=2048 && !site;y+=256){WorldPoint p{jass::Real::fromInteger(x),jass::Real::fromInteger(y)};site=session.buildSite(hero.bits,ObjectData::code("hhou"),p,reason,nullptr,nullptr,true);}require(bool(site),"No clear building site in fixture");auto blocker=call("CreateUnit",{p1,type("hfoo"),vm.real(site->x),vm.real(site->y),point(0)});require(!session.buildSite(hero.bits,ObjectData::code("hhou"),*site,reason,nullptr,nullptr,true),"Normal unit did not block building");require(call("UnitAddAbility",{blocker,type("Aeth")}).bits && session.buildSite(hero.bits,ObjectData::code("hhou"),*site,reason,nullptr,nullptr,true).has_value(),"Visible Ghost did not release building placement");require(call("UnitRemoveAbility",{blocker,type("Aeth")}).bits && !session.buildSite(hero.bits,ObjectData::code("hhou"),*site,reason,nullptr,nullptr,true),"Removed Visible Ghost still permitted building placement");require(call("UnitAddAbility",{hero,type("AOhx")}).bits,"Hex ability not added");session.advance(.1);require(!session.castSpell(hero.bits,ObjectData::code("AOhx"),target.bits),"Visible Ghost accepted a morph spell");require(call("UnitRemoveAbility",{target,type("Aeth")}).bits,"Visible Ghost removal failed");require(session.castSpell(hero.bits,ObjectData::code("AOhx"),target.bits),"Morph immunity remained after ability removal");std::cout<<"PASS visible_ghost_visibility_placement_and_morph_immunity\n";
        }else if(mode==L"flow"){
            require(!call("IssueImmediateOrder",{archer,vm.string("ambush")}).bits,"Daytime Shadow Meld accepted a hide order");daytime(0);session.advance(3);require(session.unitInvisible(archer.bits),"Nighttime idle archer did not cloak");require(call("IssuePointOrder",{archer,vm.string("move"),point(128),point(0)}).bits && !session.unitInvisible(archer.bits),"Movement did not cancel Shadow Meld");session.advance(2);require(session.unitInvisible(archer.bits),"Shadow Meld did not recover after movement");daytime(12);require(!session.unitInvisible(archer.bits),"Daylight left ordinary Shadow Meld invisible");
            require(!session.unitVisibleTo(shade.bits,0) && !call("IsVisibleToPlayer",{point(2048),point(0),p0}).bits,"Reveal fixture enemy was already visible");auto item=call("UnitAddItemById",{hero,type("crys")});require(item.bits && !call("UnitUseItem",{hero,item}).bits,"Crystal ball accepted use without a point");require(call("UnitUseItemPoint",{hero,item,point(2048),point(0)}).bits,"Crystal ball point native rejected source item");require(session.unitVisibleTo(shade.bits,0) && session.unitDetected(shade.bits,0) && !call("IsFoggedToPlayer",{point(2048),point(0),p0}).bits,"Crystal ball did not provide live terrain sight and detection");require(session.items().contains(item.bits) && !call("GetItemCharges",{item}).bits,"Unlimited source crystal ball was consumed");require(!call("UnitUseItemPoint",{hero,item,point(2048),point(0)}).bits,"Crystal ball ignored its cooldown");session.advance(10.125);require(!session.unitDetected(shade.bits,0) && session.unitInvisibleTo(shade.bits,0) && call("IsFoggedToPlayer",{point(2048),point(0),p0}).bits,"Expired crystal ball left detection or terrain sight");std::cout<<"PASS nighttime_move_daylight_ghost_crystal_ball_and_expiry\n";
        }else if(mode==L"dust"){
            move(shade,512,0);auto item=call("UnitAddItemById",{hero,type("dust")});require(item.bits && call("GetItemCharges",{item}).bits==2 && call("UnitUseItem",{hero,item}).bits,"Source dust could not be used");session.advance(.1);require(call("GetItemCharges",{item}).bits==1 && call("GetUnitAbilityLevel",{shade,type("Bdet")}).bits && session.unitDetected(shade.bits,0),"Dust did not apply source buff and consume one charge");move(shade,2048,0);require(session.unitDetected(shade.bits,0),"Dust detection was left at its casting point");require(!call("UnitUseItem",{hero,item}).bits && call("GetItemCharges",{item}).bits==1,"Dust cooldown rejection consumed a charge");session.advance(20.125);require(!session.unitDetected(shade.bits,0),"Dust did not expire");require(call("UnitUseItem",{hero,item}).bits,"Final source dust charge was rejected");session.advance(.1);require(!session.items().contains(item.bits),"Final source dust charge did not remove the item");std::cout<<"PASS dust_moving_buff_cooldown_expiry_and_consumption\n";
        }else if(mode==L"meld"){
            daytime(0);move(shade,256,0);call("UnitRemoveAbility",{shade,type("Agho")});call("SetUnitAcquireRange",{archer,point(600)});require(call("IssueImmediateOrder",{archer,vm.string("ambush")}).bits,"Manual Shadow Meld rejected its source order");session.advance(2);require(session.unitInvisible(archer.bits) && !session.units().at(archer.bits)->combat.target,"Manual Shadow Meld was interrupted by automatic acquisition");require(call("IssueTargetOrder",{archer,vm.string("attack"),shade}).bits,"Explicit attack did not leave manual Shadow Meld");require(!session.unitInvisible(archer.bits),"Explicit attack retained Shadow Meld");call("IssueImmediateOrder",{archer,vm.string("stop")});call("SetUnitAcquireRange",{archer,point(0)});call("UnitRemoveAbility",{archer,type("Ashm")});daytime(12);require(call("UnitAddAbility",{archer,type("Ahid")}).bits && call("IssueImmediateOrder",{archer,vm.string("ambush")}).bits,"Ahid source hide order was rejected");session.advance(1);require(session.unitInvisible(archer.bits),"Ahid did not cloak during daylight");call("UnitRemoveAbility",{archer,type("Ahid")});require(!session.unitInvisible(archer.bits),"Removed Shadow Meld remained effective");std::cout<<"PASS manual_hide_acquisition_explicit_attack_and_ability_removal\n";
        }else if(mode==L"sentinel"){
            auto u=session.units().at(hero.bits);auto tree=call("CreateDestructable",{type("LTlt"),vm.real(u->x),vm.real(u->y),point(0),point(1),vm.integer(0)});require(tree.bits,"Sentinel fixture tree missing");call("SetPlayerTechResearched",{p0,type("Resc"),vm.integer(1)});require(call("UnitAddAbility",{hero,type("Aesn")}).bits,"Finite Sentinel ability not added");auto finite=ObjectData::code("Aesn"),unlimited=ObjectData::code("Aesr");require(session.castSpell(hero.bits,finite,tree.bits),"Finite Sentinel order rejected");require(session.stopUnit(hero.bits),"Sentinel cancellation rejected");require(!u->sentinelCharges.contains(finite),"Canceled Sentinel consumed a charge");require(session.castSpell(hero.bits,finite,tree.bits),"Finite Sentinel recast rejected");session.advance(1);require(u->sentinelCharges.contains(finite) && !u->sentinelCharges.at(finite),"Sentinel release did not consume one charge");session.advance(121);require(!session.castSpell(hero.bits,finite,tree.bits),"Exhausted Sentinel accepted another cast");require(call("UnitRemoveAbility",{hero,type("Aesn")}).bits && call("UnitAddAbility",{hero,type("Aesn")}).bits && !u->sentinelCharges.contains(finite),"Removing and adding Sentinel did not reset charges");require(session.castSpell(hero.bits,finite,tree.bits),"Re-added Sentinel did not regain a cast");session.stopUnit(hero.bits);require(call("UnitRemoveAbility",{hero,type("Aesn")}).bits && call("UnitAddAbility",{hero,type("Aesr")}).bits,"Unlimited Sentinel ability not added");require(session.castSpell(hero.bits,unlimited,tree.bits),"Unlimited Sentinel first cast rejected");session.advance(61);require(session.castSpell(hero.bits,unlimited,tree.bits),"Zero-count Sentinel did not remain available");std::cout<<"PASS sentinel_charge_release_cancel_regrant_and_unlimited\n";
        }else{
            require(call("UnitAddAbility",{hero,type("AHta")}).bits,"Sentinel reveal ability was not added");require(!session.castSpellAt(hero.bits,ObjectData::code("AHta"),{jass::Real::fromInteger(2048),{}}),"Sentinel reveal ignored source research");call("SetPlayerTechResearched",{p0,type("Rhse"),vm.integer(1)});require(session.castSpellAt(hero.bits,ObjectData::code("AHta"),{jass::Real::fromInteger(2048),{}}),"Researched source reveal point was rejected");session.advance(1);require(session.unitVisibleTo(shade.bits,0),"Source reveal did not expose the Shade");session.advance(15.125);require(session.unitInvisibleTo(shade.bits,0),"Sentinel reveal did not expire");require(!session.castSpellAt(hero.bits,ObjectData::code("AHta"),{jass::Real::fromInteger(2048),{}}),"Sentinel reveal ignored source cooldown");std::cout<<"PASS reveal_research_point_duration_and_cooldown\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
